2.wafrica.gif", "label": "Vents 850 hPa — +12h", "description": null}, {"id": "gfs-wind850-18", "url": "https://www.cpc.ncep.noaa.gov/products/international/cpci/data/00/gfs.t00z.850mb_wind.f018.wafrica.gif", "label": "Vents 850 hPa — +18h", "description": null}, {"id": "gfs-wind850-24", "url": "https://www.cpc.ncep.noaa.gov/products/international/cpci/data/00/gfs.t00z.850mb_wind.f024.wafrica.gif", "label": "Vents 850 hPa — +24h", "description": null}]}, {"label": "Vents 700 hPa", "charts": [{"id": "gfs-wind700-06", "url": "https://www.cpc.ncep.noaa.gov/products/international/cpci/data/00/gfs.t00z.700mb_wind.f006.wafrica.gif", "label": "Vents 700 hPa — +6h", "description": null}, {"id": "gfs-wind700-12", "url": "https://www.cpc.ncep.noaa.gov/products/international/cpci/data/00/gfs.t00z.700mb_wind.f012.wafrica.gif", "label": "Vents 700 hPa — +12h", "description": null}, {"id": "gfs-wind700-18", "url": "https://www.cpc.ncep.noaa.gov/products/international/cpci/data/00/gfs.t00z.700mb_wind.f018.wafrica.gif", "label": "Vents 700 hPa — +18h", "description": null}, {"id": "gfs-wind700-24", "url": "https://www.cpc.ncep.noaa.gov/products/international/cpci/data/00/gfs.t00z.700mb_wind.f024.wafrica.gif", "label": "Vents 700 hPa — +24h", "description": null}]}, {"label": "Vents 200 hPa — Jet d'Est Tropical (TEJ)", "charts": [{"id": "gfs-wind200-06", "url": "https://www.cpc.ncep.noaa.gov/products/international/cpci/data/00/gfs.t00z.200mb_wind.f006.wafrica.gif", "label": "Vents 200 hPa — +6h", "description": "Tropical Easterly Jet — haute troposphère"}, {"id": "gfs-wind200-12", "url": "https://www.cpc.ncep.noaa.gov/products/international/cpci/data/00/gfs.t00z.200mb_wind.f012.wafrica.gif", "label": "Vents 200 hPa — +12h", "description": null}, {"id": "gfs-wind200-18", "url": "https://www.cpc.ncep.noaa.gov/products/international/cpci/data/00/gfs.t00z.200mb_wind.f018.wafrica.gif", "label": "Vents 200 hPa — +18h", "description": null}, {"id": "gfs-wind200-24", "url": "https://www.cpc.ncep.noaa.gov/products/international/cpci/data/00/gfs.t00z.200mb_wind.f024.wafrica.gif", "label": "Vents 200 hPa — +24h", "description": null}]}, {"label": "Humidité Relative 850 hPa", "charts": [{"id": "gfs-rh850-06", "url": "https://www.cpc.ncep.noaa.gov/products/international/cpci/data/00/gfs.t00z.850mb_rh.f006.wafrica.gif", "label": "HR 850 hPa — +6h", "description": "Humidité relative à 850 hPa — couche de mousson"}, {"id": "gfs-rh850-12", "url": "https://www.cpc.ncep.noaa.gov/products/international/cpci/data/00/gfs.t00z.850mb_rh.f012.wafrica.gif", "label": "HR 850 hPa — +12h", "description": null}, {"id": "gfs-rh850-18", "url": "https://www.cpc.ncep.noaa.gov/products/international/cpci/data/00/gfs.t00z.850mb_rh.f018.wafrica.gif", "label": "HR 850 hPa — +18h", "description": null}, {"id": "gfs-rh850-24", "url": "https://www.cpc.ncep.noaa.gov/products/international/cpci/data/00/gfs.t00z.850mb_rh.f024.wafrica.gif", "label": "HR 850 hPa — +24h", "description": null}]}, {"label": "Instabilité — K-Index & CAPE", "charts": [{"id": "gfs-kindex-06", "url": "https://www.cpc.ncep.noaa.gov/products/international/cpci/data/00/gfs.t00z.kindex.f006.wafrica.gif", "label": "K-Index — +6h", "description": "Indice K — potentiel d'orage convectif (>35 = fort)"}, {"id": "gfs-kindex-12", "url": "https://www.cpc.ncep.noaa.gov/products/international/cpci/data/00/gfs.t00z.kindex.f012.wafrica.gif", "label": "K-Index — +12h", "description": null}, {"id": "gfs-kindex-18", "url": "https://www.cpc.ncep.noaa.gov/products/international/cpci/data/00/gfs.t00z.kindex.f018.wafrica.gif", "label": "K-Index — +18h", "description": null}, {"id": "gfs-kindex-24", "url": "https://www.cpc.ncep.noaa.gov/products/international/cpci/data/00/gfs.t00z.kindex.f024.wafrica.gif", "label": "K-Index — +24h", "description": null}, {"id": "gfs-cape-06", "url": "https://www.cpc.ncep.noaa.gov/products/international/cpci/data/00/gfs.t00z.cape.f006.wafrica.gif", "label": "CAPE — +6h", "description": "Énergie potentielle convective disponible"}, {"id": "gfs-cape-12", "url": "https://www.cpc.ncep.noaa.gov/products/international/cpci/data/00/gfs.t00z.cape.f012.wafrica.gif", "label": "CAPE — +12h", "description": null}, {"id": "gfs-cape-18", "url": "https://www.cpc.ncep.noaa.gov/products/international/cpci/data/00/gfs.t00z.cape.f018.wafrica.gif", "label": "CAPE — +18h", "description": null}, {"id": "gfs-cape-24", "url": "https://www.cpc.ncep.noaa.gov/products/international/cpci/data/00/gfs.t00z.cape.f024.wafrica.gif", "label": "CAPE — +24h", "description": null}]}]}]$sections$::jsonb,
    $sectionNotes${"fit": "Selon ce graphe, la position du Front Intertropical (FIT) au cours de la deuxième décade du mois de mai a été située en moyenne au-dessus de sa position climatologique normale, traduisant une remontée plus au nord que la normale. ", "mjo": "La MJO (Madden-Julian Oscillation) est une perturbation atmosphérique tropicale qui se déplace d'ouest en est autour du globe avec un cycle d'environ 30 à 60 jours. \nSon évolution est représentée sur ce diagramme de phase divisé en huit cadrans (phases 1 à 8). Pour l'Afrique de l'Ouest et le Sahel, c'est principalement la phase 8 qui est surveillée car elle peut favoriser l'activité convective. \nL'intensité de la MJO dépend de sa position par rapport au centre du diagramme : lorsque la trajectoire reste proche du centre, la MJO est faible ou inactive ; lorsqu'elle s'en éloigne légèrement, elle est modérément active ; et lorsqu'elle est très éloignée du centre, elle est fortement active.\n", "nao": "L’indice NAO représente la différence de pression atmosphérique entre l’anticyclone des Açores et la dépression d’Islande. \nNAO positive\n•\tRenforcement de l’anticyclone des Açores et approfondissement de la dépression d’Islande. \n•\tIntensification de la circulation zonale d’ouest en est. \n•\tTransport accru d’air humide en provenance de l’océan Atlantique. \nNAO négative\n•\tAffaiblissement ou déplacement des centres d’action atmosphériques. \n•\tCirculation zonale moins marquée. \n•\tConditions plus froides sur le sud de l’Europe. \n", "olr": "Anomalies de vélocité potentielle (VP) à 200 hPa \n🔧 Ce que montre cette carte\n•\tContours verts : anomalies négatives de VP200 → convection renforcée\n•\tContours bruns : anomalies positives de VP200 → subsidence / air sec\n", "fit-suite": "Toutefois, elle est restée légèrement en dessous de la position observée durant la première décade de mai.", "mjo-suite": "L'analyse des diagrammes de phase de la MJO montre une divergence notable entre les modèles statistiques et le modèle dynamique GFS.\nLes modèles statistiques (CA, ARM et PCL) sont cohérents et prévoient une transition de la MJO du cadran 7 vers le cadran 8 dès le 1er ou le 2 juin, avec une MJO active sur le secteur Afrique de l'Ouest.\nEn revanche, le modèle dynamique GFS prévoit une évolution plus lente, la MJO demeurant dans le cadran 7 jusqu'aux environs du 11 juin, avant de pénétrer dans le cadran 8 avec une MJO inactive.", "nao-suite": "L'analyse des graphiques montre que l'indice NAO est resté majoritairement négatif au cours des derniers jours. Toutefois, les prévisions indiquent un retour en phase positive à partir du 2 juin.", "olr-suite": "La MJO ne soutient pas l'activité convective sur l'Afrique de l'Ouest à cette date mais si elle continue sa propagation vers l'est, elle atteindra l'Atlantique tropical et l'Afrique dans les prochains jours.", "conclusion": "Malgré quelques divergences entre les modèles, les signaux de grande échelle convergent vers une amélioration progressive du potentiel pluviométrique, avec une augmentation probable de la fréquence et de l’intensité des activités orageuses, au cours de la première quinzaine de juin. Une surveillance continue de l’évolution de la MJO et des conditions océaniques restera toutefois nécessaire pour confirmer cette tendance."}$sectionNotes$::jsonb,
    '2026-06-02 10:36:43.320375',
    '2026-06-02 10:36:43.320375'
